import { useState, type KeyboardEvent } from 'react';
import './heat-grid.css';

export interface HeatGridProps {
  /** Names the grid, for example "Wind speed by day and hour". */
  label: string;
  rows: readonly string[];
  columns: readonly string[];
  /** values[row][column] */
  values: readonly (readonly number[])[];
  formatValue?: (value: number) => string;
  /** Print each value inside its cell. */
  showValues?: boolean;
  className?: string;
}

const STEPS = 5;

/**
 * A grid of cells shaded by value, in five depth tints with a legend. Follows the WAI-ARIA
 * grid pattern: one Tab stop, arrow keys between cells, and every cell names its row,
 * column and value.
 */
export function HeatGrid({
  label,
  rows,
  columns,
  values,
  formatValue = (v) => String(v),
  showValues = false,
  className,
}: HeatGridProps) {
  const [focus, setFocus] = useState({ r: 0, c: 0 });
  const flat = values.flat();
  const min = Math.min(...flat);
  const max = Math.max(...flat);
  const step = (v: number) =>
    Math.min(STEPS - 1, Math.floor(((v - min) / (max - min || 1)) * STEPS));
  const bounds = (v: number) => min + ((max - min) * v) / STEPS;

  const move = (r: number, c: number, el: HTMLElement) => {
    const next = {
      r: Math.min(Math.max(r, 0), rows.length - 1),
      c: Math.min(Math.max(c, 0), columns.length - 1),
    };
    setFocus(next);
    el.closest('[role="grid"]')
      ?.querySelector<HTMLElement>(`[data-cell="${next.r}-${next.c}"]`)
      ?.focus();
  };

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const { r, c } = focus;
    const moves: Record<string, [number, number]> = {
      ArrowRight: [r, c + 1],
      ArrowLeft: [r, c - 1],
      ArrowDown: [r + 1, c],
      ArrowUp: [r - 1, c],
      Home: event.ctrlKey ? [0, 0] : [r, 0],
      End: event.ctrlKey ? [rows.length - 1, columns.length - 1] : [r, columns.length - 1],
    };
    const target = moves[event.key];
    if (!target) return;
    event.preventDefault();
    move(target[0], target[1], event.target as HTMLElement);
  };

  return (
    <figure className={['atl-heat', className].filter(Boolean).join(' ')}>
      {/* The cells take focus (roving tabindex); the grid only routes their arrow keys. */}
      {/* eslint-disable-next-line jsx-a11y/interactive-supports-focus */}
      <div
        role="grid"
        aria-label={label}
        className="atl-heat__grid"
        onKeyDown={onKeyDown}
        style={{ '--cols': columns.length } as React.CSSProperties}
      >
        <div role="row" className="atl-heat__row">
          <span role="columnheader" className="atl-heat__corner" aria-hidden="true" />
          {columns.map((col) => (
            <span key={col} role="columnheader" className="atl-heat__colhead">
              {col}
            </span>
          ))}
        </div>
        {rows.map((row, r) => (
          <div key={row} role="row" className="atl-heat__row">
            <span role="rowheader" className="atl-heat__rowhead">
              {row}
            </span>
            {columns.map((col, c) => {
              const value = values[r]?.[c] ?? 0;
              return (
                // Keys are handled once on the grid (WAI-ARIA grid pattern).
                // eslint-disable-next-line jsx-a11y/click-events-have-key-events
                <span
                  key={col}
                  role="gridcell"
                  tabIndex={focus.r === r && focus.c === c ? 0 : -1}
                  data-cell={`${r}-${c}`}
                  data-step={step(value)}
                  className="atl-heat__cell"
                  aria-label={`${row}, ${col}: ${formatValue(value)}`}
                  onFocus={() => setFocus({ r, c })}
                  onClick={(event) => move(r, c, event.currentTarget)}
                >
                  <span
                    className="atl-heat__value"
                    aria-hidden="true"
                    data-visible={showValues || undefined}
                  >
                    {formatValue(value)}
                  </span>
                </span>
              );
            })}
          </div>
        ))}
      </div>
      <figcaption className="atl-heat__legend" aria-hidden="true">
        {Array.from({ length: STEPS }, (_, i) => (
          <span key={i} className="atl-heat__key">
            <span className="atl-heat__swatch" data-step={i} />
            {formatValue(Math.round(bounds(i)))}–{formatValue(Math.round(bounds(i + 1)))}
          </span>
        ))}
      </figcaption>
    </figure>
  );
}

@layer atlas.components {
  .atl-heat {
    display: grid;
    gap: var(--space-s);
    margin: 0;
    max-width: 100%;
    overflow-x: auto;
  }

  .atl-heat__grid {
    display: grid;
    gap: 3px;
    width: max-content;
  }

  .atl-heat__row {
    display: grid;
    grid-template-columns: 3.5rem repeat(var(--cols), 2.25rem);
    gap: 3px;
    align-items: center;
  }

  .atl-heat__colhead,
  .atl-heat__rowhead {
    color: var(--ink-soft);
    font-size: 0.75rem;
    font-variant-numeric: tabular-nums;
  }

  .atl-heat__colhead {
    text-align: center;
  }

  /* Depth tints: deeper water, darker cell in the night theme; the reverse by day. */
  .atl-heat__cell,
  .atl-heat__swatch {
    --atl-heat: color-mix(in oklch, var(--ink) calc(8% + var(--s, 0) * 21%), var(--sea-1));
  }

  [data-step='0'] {
    --s: 0;
  }
  [data-step='1'] {
    --s: 1;
  }
  [data-step='2'] {
    --s: 2;
  }
  [data-step='3'] {
    --s: 3;
  }
  [data-step='4'] {
    --s: 4;
  }

  .atl-heat__cell {
    display: grid;
    place-items: center;
    height: 2.25rem;
    border-radius: 4px;
    background: var(--atl-heat);
    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--isobath) 40%, transparent);
    cursor: pointer;
  }

  .atl-heat__cell:focus-visible {
    outline: var(--focus-ring);
    outline-offset: 1px;
    z-index: 1;
  }

  .atl-heat__value {
    font-size: 0.7rem;
    font-weight: 600;
    font-variant-numeric: tabular-nums;
    color: var(--ink);
    opacity: 0;
  }

  .atl-heat__cell[data-step='2'] .atl-heat__value,
  .atl-heat__cell[data-step='3'] .atl-heat__value,
  .atl-heat__cell[data-step='4'] .atl-heat__value {
    color: var(--sea-0);
  }

  .atl-heat__value[data-visible],
  .atl-heat__cell:focus-visible .atl-heat__value,
  .atl-heat__cell:hover .atl-heat__value {
    opacity: 1;
  }

  .atl-heat__legend {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-xs) var(--space-s);
    color: var(--ink-soft);
    font-size: 0.75rem;
  }

  .atl-heat__key {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2xs);
  }

  .atl-heat__swatch {
    width: 14px;
    height: 14px;
    border-radius: 3px;
    background: var(--atl-heat);
    box-shadow: inset 0 0 0 1px var(--isobath);
  }
}
